/** 返回固定期望话题列表（有数据的按播放量排前面，无数据的排后面） */
export function getAllTopicsSorted() {
  const latestDate = DATES[DATES.length - 1];
  const volumeMap = {};
  Object.values(RAW_DATA).forEach((records) => {
    records.forEach((record) => {
      if (!volumeMap[record.t]) volumeMap[record.t] = 0;
      if (record.d === latestDate && record.v != null) {
        volumeMap[record.t] += record.v;
      }
    });
  });
  return EXPECTED_TOPICS.slice().sort((a, b) => (volumeMap[b] || 0) - (volumeMap[a] || 0));
}

/** 兼容旧接口 */
export const getAllTopics = getAllTopicsSorted;

/** 获取指定平台的数据 */
export function getPlatformData(platformKey) {
  return RAW_DATA[platformKey] || [];
}

/** 获取指定平台的作品数数据 */
export function getWorkCountData(platformKey) {
  return (typeof WORK_COUNT !== 'undefined' && WORK_COUNT[platformKey]) || [];
}

/** 获取活跃平台列表（支持多选数组） */
export function getSelectedPlatforms(selectedKeys) {
  return PLATFORMS.filter((p) => p.key !== 'all' && selectedKeys.includes(p.key));
}

/** 获取筛选后的日期列表 */
export function getFilteredDates(dateStart, dateEnd) {
  if (dateStart && dateEnd) {
    return DATES.filter((d) => d >= dateStart && d <= dateEnd);
  }
  return DATES;
}

/** 格式化播放量数值（输入单位：亿） */
export function formatVolume(value) {
  if (value == null) return '-';
  if (value >= 10000) return (value / 10000).toFixed(1) + '万亿';
  if (value >= 1) return value.toFixed(1) + '亿';
  return (value * 10000).toFixed(0) + '万';
}

/** HTML 转义，防止数据（话题名/公司/品类等）注入 DOM 造成 XSS */
export function escapeHtml(value) {
  if (value == null) return '';
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/** 本地日期字符串 YYYY-MM-DD（统一各模块，避免重复实现） */
export function formatDateLocal(date) {
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
}

/** 最新可选日期：小于今天的最晚一天（未发布数据不展示） */
export function latestSelectableDate() {
  const today = formatDateLocal(new Date());
  const available = DATES.filter((d) => d < today);
  return available[available.length - 1] || DATES[DATES.length - 1];
}

/** 日期 -> 索引 缓存，避免反复 indexOf 线性扫描 */
const _dateIndex = new Map(DATES.map((d, i) => [d, i]));

/** 某日期的前一日（无则返回 null） */
export function getPreviousDate(date) {
  const idx = _dateIndex.get(date);
  return idx > 0 ? DATES[idx - 1] : null;
}

/** 将记录数组按 日期 -> 话题 -> 记录 建立两级索引，把 find 线性扫描降为 O(1) */
export function indexByDateTopic(records) {
  const byDate = new Map();
  for (const r of records) {
    let byTopic = byDate.get(r.d);
    if (!byTopic) { byTopic = new Map(); byDate.set(r.d, byTopic); }
    byTopic.set(r.t, r);
  }
  return byDate;
}

/** 从索引中取某日期某话题的记录（无则 null） */
export function lookupRecord(index, date, topic) {
  const byTopic = index.get(date);
  return byTopic ? byTopic.get(topic) : null;
}
